const material=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.85,...extra});const matStone=material(0x615367),matDark=material(0x332e48),matGold=material(0xb6884b),matPurple=material(0x493456);
function mesh(geo,mat,pos,parent=world){const m=new T.Mesh(geo,mat);m.position.set(...pos);parent.add(m);return m;}
function box(w,h,d,x,y,z,mat=matStone){return mesh(new T.BoxGeometry(w,h,d),mat,[x,y,z]);}
function cylinder(r,h,x,y,z,mat=matGold){return mesh(new T.CylinderGeometry(r,r,h,12),mat,[x,y,z]);}
function glow(color,x,y,z,power=3,distance=6){const light=new T.PointLight(color,power,distance,1.5);light.position.set(x,y,z);world.add(light);return light;}
function save(){if(!started||clearingSave)return;try{localStorage.setItem(SAVE,JSON.stringify({...state,music:soundscape.journeyState(),dog:actors.dog?.root.position.toArray(),position:player.position.toArray(),elena:actors.elena?.root.position.toArray()}));}catch{}}
