const noise=(i)=>{const n=Math.sin(i*91.323)*43758.545;return n-Math.floor(n)};
function buildGround(){
 box(13,.45,14.3,0,-.25,7,matDark);box(11,.4,13,0,-.22,36.5,matDark);
 const geo=new T.BoxGeometry(.68,.1,.68), tiles=new T.InstancedMesh(geo,matStone,750),dummy=new T.Object3D();let i=0;
 for(let z=.4;z<14;z+=.73)for(let x=-5.85;x<6;x+=.73){dummy.position.set(x,-.035,z);dummy.rotation.y=(noise(i)-.5)*.035;dummy.updateMatrix();tiles.setMatrixAt(i,dummy.matrix);tiles.setColorAt(i,new T.Color().setHSL(.75,.08,.29+noise(i)*.09));i++;}
 for(let z=30;z<42;z+=.73)for(let x=-3.3;x<3.4;x+=.73){dummy.position.set(x,-.035,z);dummy.updateMatrix();tiles.setMatrixAt(i,dummy.matrix);tiles.setColorAt(i,new T.Color(0x6e5d72));i++;}tiles.count=i;world.add(tiles);
 // Walking bounds are mathematical; no visible replacement deck covers the source bridge.

 for(let side of [-1,1]){box(.18,.3,14,side*6.15,.03,7,matGold);for(let z=1;z<13;z+=2.6){cylinder(.16,.65,side*6.1,.35,z,matPurple);mesh(new T.SphereGeometry(.2,8,8),material(0xc5873b),[side*6.1,.74,z]);}}
 // Two-colour petal trail joins all three memories to the bridge.
 const petals=new T.InstancedMesh(new T.SphereGeometry(.07,5,4),material(0xf6a32c),1100);for(let j=0;j<1100;j++){let z=noise(j+12)*39,x;if(z<14)x=(noise(j+66)-.5)*1.8;else if(z<30)x=(noise(j+66)-.5)*2.5;else x=(noise(j+66)-.5)*1.7;dummy.position.set(x,.06,z);dummy.scale.set(1,.25,.65);dummy.rotation.set(0,noise(j+23)*6.28,0);dummy.updateMatrix();petals.setMatrixAt(j,dummy.matrix);petals.setColorAt(j,new T.Color(j%4?0xed9229:0xffbf3b));}world.add(petals);
 const under=new T.Mesh(new T.PlaneGeometry(250,250),material(0x1a1830,{metalness:.4,roughness:.35}));under.rotation.x=-Math.PI/2;under.position.y=-4.5;world.add(under);
 // Distant city and living town are built in world-depth.js.
 const starGeo=new T.BufferGeometry(),positions=[];for(let j=0;j<550;j++){positions.push((noise(j)-.5)*160,13+noise(j+7)*55,(noise(j+17)-.2)*130);}starGeo.setAttribute('position',new T.Float32BufferAttribute(positions,3));world.add(new T.Points(starGeo,new T.PointsMaterial({color:0xf6dfbf,size:.07,transparent:true,opacity:.75})));
 const moonDisk=mesh(new T.SphereGeometry(2.4,32,24),new T.MeshBasicMaterial({color:0xffd6a7}),[-23,27,65]);
 // Quiet floating lights make the negative space readable without filling the route.
 const fireGeo=new T.BufferGeometry(),fp=[];for(let j=0;j<100;j++)fp.push((noise(j+1)-.5)*14,.5+noise(j+3)*4,noise(j+5)*37);fireGeo.setAttribute('position',new T.Float32BufferAttribute(fp,3));const fire=new T.Points(fireGeo,new T.PointsMaterial({color:0xffcb79,size:.055,transparent:true,opacity:.8}));world.add(fire);assets.fire=fire;
 for(const [x,z] of [[-3.5,4],[3.3,7],[-3.25,10.4]]){const h=z===4?.52:z===7?.86:.8;box(.95,h,.8,x,h/2,z,material(0x594059));box(1.08,.09,.91,x,h+.025,z,matGold);colliders.push({x,z,w:1.1,d:.95});}
 for(const [x,z] of [[-5.5,2],[5.5,3],[-5.5,8],[5.6,11]]){cylinder(.34,.5,x,.25,z,material(0x6b4f73));for(let n=0;n<5;n++)mesh(new T.IcosahedronGeometry(.23,1),material(n%2?0xe89129:0xf4ac2f),[x+Math.cos(n*1.6)*.17,.65+noise(n)*.2,z+Math.sin(n*1.6)*.17]);}
}
