const loadManager=new T.LoadingManager(),loader=new GLTFLoader(loadManager);let loadedCount=0;const paths=['bridge-straight','kitchen','altar-remembrance','dante-walk','chapel','arch','shoe-v2','book-closed','book-open','paper-flower','frame-empty','lantern','elena-walk-tripo','luna-new','apprentice-walk-pickup-tripo','npc-baker','npc-musician','npc-lamplighter'];
async function loadAssets(){for(const name of paths){$('#loadtext').textContent=`正在整理 ${name.includes('tripo')?'人物与动作':'场景与旧物'} · ${loadedCount+1} / ${paths.length}`;assets[name]=await loader.loadAsync(`assets/models/${name}-game.glb`);if(name==='dante-walk'&&assets[name].animations[0])assets[name].animations[0].name='walk';loadedCount++;$('#loadbar').style.width=`${loadedCount/paths.length*100}%`;}buildModels();ready();}
function placed(name,width,pos,rotation=0){const wrapper=new T.Group(),root=assets[name].scene.clone(true);wrapper.add(root);const b=new T.Box3().setFromObject(root),s=b.getSize(new T.Vector3()),c=b.getCenter(new T.Vector3());const scale=width/s.x;root.position.set(-c.x,-b.min.y,-c.z);wrapper.scale.setScalar(scale);wrapper.position.set(...pos);wrapper.rotation.y=rotation;world.add(wrapper);return wrapper;}
function character(key,name,height,pos){const outer=new T.Group(),model=cloneSkeleton(assets[name].scene);outer.add(model);const b=new T.Box3().setFromObject(model),s=b.getSize(new T.Vector3()),center=b.getCenter(new T.Vector3()),modelScale=height/s.y;model.scale.setScalar(modelScale);model.position.set(-center.x*modelScale,-b.min.y*modelScale,-center.z*modelScale);outer.position.set(...pos);world.add(outer);const mixer=new T.AnimationMixer(model),clips=assets[name].animations.map(c=>c.clone());for(const clip of clips){if(clip.name!=='walk'&&clip.name!=='model-action')continue;for(const track of clip.tracks){if(!track.name.includes('Hips')||!track.name.endsWith('.position'))continue;const v=track.values,last=v.length-3,dx=v[last]-v[0],dz=v[last+2]-v[2];for(let i=0;i<track.times.length;i++){const fraction=track.times[i]/clip.duration;v[i*3]-=dx*fraction;v[i*3+2]-=dz*fraction;}}}const walk=clips.find(c=>c.name==='walk')||clips.find(c=>c.name==='model-action'),a={root:outer,model,mixer,clips,walk:walk?mixer.clipAction(walk):null,moving:false,pick:null};a.restPose=[];model.traverse(b=>{if(b.isBone)a.restPose.push({bone:b,q:b.quaternion.clone(),p:b.position.clone()});});actors[key]=a;if(a.walk){a.walk.play();a.walk.time=.12;a.walk.paused=true;mixer.update(0);}return a;}
