 const apprentice=character('apprentice','apprentice-walk-pickup-tripo',1.4,[0,0,1]);world.remove(apprentice.root);player.add(apprentice.root);apprentice.root.position.set(0,0,0);
 // Keep the empty frame at the waiting place: the walk clip has no carrying pose.
 box(.72,.72,.65,2.8,.36,11.8,matPurple);box(.8,.08,.73,2.8,.76,11.8,matGold);
 placed('frame-empty',.42,[2.8,.81,11.8],Math.PI);colliders.push({x:2.8,z:11.8,w:.8,d:.73});
 for(const [key,data] of Object.entries(MEMORIES)){const prop=placed(data.model,data.size,data.pos,key==='recipe'?-.4:.3);assets[key+'Prop']=prop;const ring=mesh(new T.TorusGeometry(.5,.012,5,48),new T.MeshBasicMaterial({color:0xf2ba63,transparent:true,opacity:.7}),[data.pos[0],.09,data.pos[2]]);ring.rotation.x=-Math.PI/2;const beacon=glow(0xffbd61,data.pos[0],data.pos[1]+.25,data.pos[2],1.5,3.3);const button=document.createElement('button');button.className='location';button.innerHTML=`${data.name}<small>${data.place}</small>`;button.addEventListener('click',()=>goTo(key));$('#locations').append(button);hotspots.push({key,data,prop,ring,beacon,button});}
 const npcButton=document.createElement('button');npcButton.className='location';npcButton.innerHTML='伊莲娜<small>桥边的等候者</small>';npcButton.onclick=()=>goTo('elena');$('#locations').append(npcButton);assets.npcButton=npcButton;
 for(let i=0;i<3;i++){const x=i===1?2.4:-2.4,z=17+i*5;box(.55,.5,.55,x,.25,z,matPurple);const l=placed('lantern',.65,[x,.5,z]);const bulb=mesh(new T.SphereGeometry(.11,12,12),material(0xe7b06a,{emissive:0xffad30,emissiveIntensity:0}),[x,1.15,z]);const light=glow(0xffad42,x,1.5,z,0,9);lamps.push({model:l,bulb,light,amount:0});}
 assets.barrier=bridgeJourney.barrier;
 const gateLight=glow(0xffc77a,0,3.4,32,9,14);assets.gateLight=gateLight;
 const gatePlane=mesh(new T.PlaneGeometry(3.3,4.6),new T.MeshBasicMaterial({color:0xffd795,transparent:true,opacity:.12,side:T.DoubleSide,depthWrite:false}),[0,2.3,32]);assets.gatePlane=gatePlane;
 buildNPCs();makePhoto();assets.photo.visible=false;
