function talkToNpc(key){const n=NPCS[key];if(!n)return;let lines=npcConversation(key,state);showDialog({title:n.role+' · '+n.name,kicker:'广场上的人',object:n.object,tag:state.found.length+' / 3 段记忆',lines,button:key==='musician'?'听他续上一小段':'谢谢，继续走走',onDone:()=>{if(key==='musician')soundscape.phrase(state.found.length+1);else if(key==='keeper'&&state.found.length<3)toast('旧物不分先后。「为我指路」会带你走近最近的一件。');}});}
function updateNPCs(dt){for(const n of npcSpots){if(n.key==='keeper'&&!modal&&player.position.distanceTo(n.actor.root.position)>2.2){const goal=12+Math.sin(time*.22)*.35,delta=goal-n.actor.root.position.z;n.actor.root.position.z+=Math.sign(delta)*Math.min(Math.abs(delta),dt*.23);n.actor.root.rotation.y=delta>=0?0:Math.PI;setWalking(n.actor,Math.abs(delta)>.03,dt*.3);}else{setWalking(n.actor,false,dt);if(player.position.distanceTo(n.actor.root.position)<2.5)n.actor.root.rotation.y=Math.atan2(player.position.x-n.actor.root.position.x,player.position.z-n.actor.root.position.z);}}}
function updateDog(dt){
 const a=actors.dog;if(!a)return;if(assets.dogInteracting&&!autoTarget&&!modal)assets.dogInteracting=false;
 let goal,mode='follow';const p=player.position,dist=a.root.position.distanceTo(p);
 if(state.phase==='EXPLORE'){
  const remaining=Object.keys(MEMORIES).filter(k=>!state.found.includes(k));remaining.sort((x,y)=>p.distanceTo(new T.Vector3(...MEMORIES[x].stand))-p.distanceTo(new T.Vector3(...MEMORIES[y].stand)));
  if(remaining.length){goal=new T.Vector3(...MEMORIES[remaining[0]].stand).add(new T.Vector3(-.45,0,-.4));mode='guide';}else goal=p.clone().add(new T.Vector3(-.8,0,-.5));
 }else if(state.phase==='TO_GATE'){goal=new T.Vector3(-.65,0,Math.min(30.4,Math.max(12.3,p.z+1.25)));mode='bridge';}
 else if(['ENDING','COMPLETE'].includes(state.phase)&&!freeRoam){goal=new T.Vector3(-.75,0,33.2);mode='wait';}
 else goal=p.clone().add(new T.Vector3(-.8,0,-.6));
 if((a.root.position.z>30&&goal.z<30)||(a.root.position.z<14&&goal.z>14))goal=new T.Vector3(-.65,0,a.root.position.z>30?29.4:14.5);
 else if(a.root.position.z>14&&a.root.position.z<30){goal.x=-.65;goal.z=T.MathUtils.clamp(goal.z,13.4,30.6);}
 goal.x=T.MathUtils.clamp(goal.x,-5.3,5.3);goal.z=T.MathUtils.clamp(goal.z,.6,39);
 const ahead=mode==='guide'&&dist>4&&a.root.position.distanceTo(goal)<p.distanceTo(goal),stopped=!!modal||assets.dogInteracting||ahead;
 const dir=goal.clone().sub(a.root.position);dir.y=0;let moved=false;
 if(!stopped&&dir.length()>.16){const speed=dist>3?2.05:1.15,step=Math.min(dir.length(),dt*speed),candidate=a.root.position.clone().addScaledVector(dir.normalize(),step);if(candidate.z>13.3&&candidate.z<30)candidate.x=T.MathUtils.clamp(candidate.x,-.95,.95);
  const free=v=>!colliders.some(c=>Math.abs(v.x-c.x)<c.w/2+.16&&Math.abs(v.z-c.z)<c.d/2+.16);
  if(free(candidate)){a.root.position.copy(candidate);moved=true;}else{const slide=a.root.position.clone();slide.x=candidate.x;if(free(slide)){a.root.position.copy(slide);moved=true;}else{slide.copy(a.root.position);slide.z=candidate.z;if(free(slide)){a.root.position.copy(slide);moved=true;}}}
  const angle=Math.atan2(dir.x,dir.z);a.root.rotation.y+=Math.atan2(Math.sin(angle-a.root.rotation.y),Math.cos(angle-a.root.rotation.y))*Math.min(1,dt*7);
 }
 setWalking(a,moved,dt*(dist>3?2.5:1.5));if(!moved){resetPose(a);const look=p.clone().sub(a.root.position);a.root.rotation.y+=Math.atan2(Math.sin(Math.atan2(look.x,look.z)-a.root.rotation.y),Math.cos(Math.atan2(look.x,look.z)-a.root.rotation.y))*Math.min(1,dt*3);if(a.head)a.head.rotation.z+=Math.sin(time*1.8)*(time<(assets.dogPetUntil||0)?.09:.015);}
 $('#world').dataset.dogMode=modal?'waiting':moved?mode:'waiting';$('#world').dataset.dogPosition=a.root.position.toArray().map(n=>n.toFixed(2)).join(',');$('#world').dataset.dogClip=a.walk?.getClip().name||'none';$('#world').dataset.dogAnimationTime=(a.walk?.time||0).toFixed(3);
}
function applyCreations(){const c=state.creations?.flower;if(c&&!assets.keepsakeFlower){const root=new T.Group(),color={orange:0xee9b38,gold:0xf0ca65,rose:0xd68a9c}[c.color]||0xee9b38;const stem=new T.Mesh(new T.CylinderGeometry(.006,.009,.27,6),material(0x6c8150));stem.position.y=.135;root.add(stem);for(let i=0;i<12;i++){const angle=i*Math.PI/6,dir=new T.Vector3(Math.cos(angle),Math.sin(angle),0),side=new T.Vector3(-dir.y,dir.x,0),base=new T.Vector3(0,.28,0),tip=base.clone().addScaledVector(dir,.13),left=base.clone().addScaledVector(dir,.065).addScaledVector(side,.035),right=base.clone().addScaledVector(dir,.065).addScaledVector(side,-.035),ridge=base.clone().addScaledVector(dir,.072).add(new T.Vector3(0,0,.035));const points=[base,left,ridge,left,tip,ridge,tip,right,ridge,right,base,ridge],g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(points.flatMap(v=>v.toArray()),3));g.computeVertexNormals();root.add(new T.Mesh(g,material(color,{side:T.DoubleSide})));}root.rotation.y=.25;root.position.set(-.26,.84,37.47);world.add(root);assets.keepsakeFlower=root;}if(assets.keepsakeFlower)assets.keepsakeFlower.visible=state.found.length===3;if(state.creations.recipe&&!assets.keepsakeSweets){const g=new T.Group(),plate=new T.Mesh(new T.CylinderGeometry(.16,.13,.025,20),material(0x9b698f));g.add(plate);for(let i=0;i<3;i++){const bun=new T.Mesh(new T.SphereGeometry(.06,10,7),material(0xd99450));bun.scale.y=.65;bun.position.set((i-1)*.085,.045,Math.abs(i-1)*.025);g.add(bun);}for(let i=0;i<Math.min(3,Math.max(1,Number(state.creations.recipe.sugar)||2));i++){const sugar=new T.Mesh(new T.SphereGeometry(.012,6,4),material(0xffedd1));sugar.position.set((i-1)*.04,.105,0);g.add(sugar);}g.position.set(.75,.84,37.44);world.add(g);assets.keepsakeSweets=g;}if(assets.keepsakeSweets)assets.keepsakeSweets.visible=state.found.length===3;}
function updateCompanion(){if(modal){$('#companionLine').classList.remove('show');return;}if(state.phase==='TO_GATE'&&time>=companionUntil){for(let i=0;i<3;i++){if(player.position.z>16+i*5&&!companionHeard.has(i)){companionHeard.add(i);const lines=['以前总怕她摔倒。后来才明白，系好鞋带，是为了让她放心往前跑。','你选的味道是'+recipeEcho(state.creations)+'。她也会有自己的做法。','这朵'+({orange:'橙色',gold:'金色',rose:'粉色'}[state.creations.flower?.color]||'橙色')+'的花，会有自己的窗台。谢谢你陪我。'];$('#companionLine').textContent='伊莲娜：'+lines[i];$('#companionLine').classList.add('show');companionUntil=time+3.8;break;}}}if(time>companionUntil)$('#companionLine').classList.remove('show');}
function resetPose(a){for(const r of a.restPose){r.bone.quaternion.copy(r.q);r.bone.position.copy(r.p);}a.root.updateMatrixWorld(true);}
function bone(a,name){return a.model.getObjectByName('mixamorig:'+name)||a.model.getObjectByName('mixamorig'+name);}
function solveArm(a,side,localTarget){const upper=bone(a,side+'Arm'),fore=bone(a,side+'ForeArm'),hand=bone(a,side+'Hand');if(!upper||!fore||!hand)return;const target=a.root.localToWorld(localTarget.clone());for(let i=0;i<7;i++)for(const joint of [fore,upper]){a.root.updateMatrixWorld(true);const origin=joint.getWorldPosition(new T.Vector3()),end=hand.getWorldPosition(new T.Vector3()).sub(origin).normalize(),want=target.clone().sub(origin).normalize();if(end.lengthSq()<.1||want.lengthSq()<.1)continue;const delta=new T.Quaternion().setFromUnitVectors(end,want),angle=2*Math.acos(T.MathUtils.clamp(delta.w,-1,1));if(angle>.32)delta.slerp(new T.Quaternion(),1-.32/angle);const parent=joint.parent.getWorldQuaternion(new T.Quaternion()),local=parent.clone().invert().multiply(delta).multiply(parent);joint.quaternion.premultiply(local).normalize();}a.root.updateMatrixWorld(true);}
function poseLuna(mode,amount=0){const a=actors.luna;if(!a)return;resetPose(a);const chest=bone(a,'Spine2')||bone(a,'Spine');if(chest)chest.rotation.x+=Math.sin(time*1.5)*.008+(mode==='reach'?.1*amount:0);for(const [side,x]of[['Left',.12],['Right',-.12]]){let goal=mode==='idle'?new T.Vector3(x*1.5,.43,.025):new T.Vector3(x,.73,.2);if(mode==='reach')goal.lerp(new T.Vector3(x,.9,.35),amount);solveArm(a,side,goal);}a.root.updateMatrixWorld(true);}
function updateLuna(dt){
 const a=actors.luna;if(!a)return;const seq=assets.lunaSequence;
 if(!seq||seq.placed){setWalking(a,false,dt);poseLuna('idle');reportPhoto();return;}
 const run=(state.phase==='PHOTO'&&dialog?.index>=1)||['TO_GATE','ENDING','COMPLETE'].includes(state.phase);
 if(!run){setWalking(a,false,dt);poseLuna('idle');reportPhoto();return;}
 seq.elapsed+=dt;const target=new T.Vector3(.2,0,36.98),dir=target.clone().sub(a.root.position);dir.y=0;
 if(dir.length()>.04){a.root.position.addScaledVector(dir.normalize(),Math.min(dir.length(),dt*.8));a.root.rotation.y=Math.atan2(dir.x,dir.z);setWalking(a,true,dt);updateLunaPhoto('hold',0);reportPhoto();return;}
 setWalking(a,false,dt);a.root.rotation.y=0;a.root.position.y=0;
 if((state.phase==='PHOTO'&&dialog?.index>=2)||state.phase!=='PHOTO'){
  seq.placeTime=(seq.placeTime||0)+dt;const t=Math.min(1,seq.placeTime/2.8);poseLuna('reach',Math.min(1,t*1.5));updateLunaPhoto('place',t);
  if(t===1){seq.placed=true;state.photoPlaced=true;save();assets.photo.position.copy(assets.photoTarget);assets.photo.rotation.set(0,Math.PI,0);assets.photo.visible=true;poseLuna('idle');if(dialog&&state.phase==='PHOTO')renderLine();}
 }else{poseLuna('hold');updateLunaPhoto('hold',0);}reportPhoto();
}
function updateLunaPhoto(mode,t){
 const a=actors.luna,photo=assets.photo;photo.visible=true;const l=bone(a,'LeftHand'),r=bone(a,'RightHand');let point=a.root.localToWorld(new T.Vector3(0,.79,.22));
 if(l&&r)point=l.getWorldPosition(new T.Vector3()).add(r.getWorldPosition(new T.Vector3())).multiplyScalar(.5).add(new T.Vector3(0,.055,.015));
 if(mode==='place'){const amount=T.MathUtils.smoothstep(t,.25,.88);point.lerp(assets.photoTarget,amount);}
 photo.position.copy(point);photo.rotation.set(0,mode==='place'?Math.PI:a.root.rotation.y+Math.PI,0);
}
function reportPhoto(){if(assets.photoLight)assets.photoLight.intensity=T.MathUtils.lerp(assets.photoLight.intensity,state.photoPlaced?2:.35,.035);const el=$('#world');el.dataset.altar='original-ornate-single-frame';el.dataset.photoStage=assets.lunaSequence?(assets.lunaSequence.placed?'placed':assets.lunaSequence.placeTime?'placing':assets.lunaSequence.elapsed?'carrying':'waiting'):assets.photo?.visible?'placed':'empty';el.dataset.photoVisible=String(!!assets.photo?.visible);el.dataset.photoPosition=assets.photo?.position.toArray().map(n=>n.toFixed(3)).join(',')||'';el.dataset.photoTarget=assets.photoTarget?.toArray().map(n=>n.toFixed(3)).join(',')||'';}

function ready(){ $('#loading').hidden=true;$('#welcome').hidden=false;$('#continueBtn').hidden=!saved;$('#hud').style.opacity='0';$('#controls').style.opacity='0';updateHUD();}
function start(resume=false){bridgeJourney.reset();soundscape.resetJourney(resume?saved?.music||{}:{});freeRoam=false;companionHeard.clear();if(wantsSound)enableSound();state=resume?restore(saved):initialState();started=true;paused=false;closeModal('#welcome');$('#hud').style.opacity='1';$('#controls').style.opacity='1';if(resume&&saved.position&&saved.position.every(Number.isFinite))player.position.fromArray(saved.position);else player.position.set(0,0,1);if(resume&&saved.elena)actors.elena.root.position.fromArray(saved.elena);else actors.elena.root.position.set(1.6,0,12);if(resume&&actors.dog){if(Array.isArray(saved.dog)&&saved.dog.length===3&&saved.dog.every(Number.isFinite)){actors.dog.root.position.set(T.MathUtils.clamp(saved.dog[0],-5.3,5.3),0,T.MathUtils.clamp(saved.dog[2],.6,39));}else actors.dog.root.position.set(player.position.z>13.3?-.65:player.position.x+.7,0,Math.max(.6,player.position.z-.8));}for(const h of hotspots){h.prop.visible=!state.found.includes(h.key);}if(['TO_GATE','ENDING','COMPLETE'].includes(state.phase)&&player.position.z>14.05){state.bridgeCrossed=true;if(state.phase==='TO_GATE')soundscape.beginJourney();}applyState();if(state.phase==='OPENING')opening();else if(state.phase==='PHOTO')photoReveal();else if(state.phase==='ENDING')endingScene();else if(state.phase==='COMPLETE')complete();else toast('旅程已继续。点击地标走近，按 E 调查。');save();}
function updateHUD(){const count=state.found.length;$('#progress span').textContent=`${count} / 3 段记忆`;$('#progress').querySelectorAll('i').forEach((el,i)=>el.classList.toggle('lit',state.found.includes(Object.keys(MEMORIES)[i])));const p=state.phase;$('#chapter').textContent=freeRoam?'后记 · 灯火未散':p==='OPENING'?'序章 · 桥边的等候者':['EXPLORE','MEMORY'].includes(p)?'第一章 · 旧物里的光':p==='PHOTO'?'第二章 · 认出她的人':'第三章 · 陪你回家';$('#objective').textContent=freeRoam?'听完那支曲子，看看你亲手留下的花。':p==='OPENING'?'有人在桥边，等一盏回家的灯。':['EXPLORE','MEMORY'].includes(p)?`寻找红鞋、食谱与纸花，点亮三盏桥灯。` :p==='PHOTO'?'三段记忆拼出了她的模样。':p==='COMPLETE'?'今晚，有一盏灯为她留着。':'陪伊莲娜沿花桥走向暖光中的城门。';for(const h of hotspots){h.button.classList.toggle('done',state.found.includes(h.key));h.ring.material.color.set(state.found.includes(h.key)?0x857298:0xf2ba63);} }
function applyState(){if(assets.nextLetter)assets.nextLetter.visible=state.phase==='COMPLETE';const unlocked=['TO_GATE','ENDING','COMPLETE'].includes(state.phase);assets.barrier.visible=true;assets.photo.visible=unlocked&&(!assets.lunaSequence||assets.lunaSequence.placed);if(unlocked&&!assets.lunaSequence){actors.luna.root.position.set(.2,0,36.98);actors.luna.root.rotation.y=0;assets.photo.position.copy(assets.photoTarget);}applyCreations();for(const h of hotspots)h.prop.visible=!state.found.includes(h.key);updateHUD();}
function showDialog({title,kicker,lines,object=null,tag='',onDone,button='继续',replay=false}){dialog={title,kicker,lines,index:0,onDone,button,replay};$('#dialogTitle').textContent=title;$('#dialogKicker').textContent=kicker;$('#memoryTag').textContent=tag;setInspection(object);openModal('#dialogue');renderLine();$('#nextBtn').focus();}
function renderLine(){const d=dialog;if(d.index>0)soundscape.play('page-turn',.7);$('#dialogue').classList.toggle('cinematic',(state.phase==='PHOTO'&&d.index>=1)||state.phase==='ENDING'||d.kicker?.startsWith('但丁'));$('#speaker').textContent=d.lines[d.index][0];$('#line').textContent=d.lines[d.index][1];$('#dialogDots').innerHTML=d.lines.map((_,i)=>`<i class="${i<=d.index?'on':''}"></i>`).join('');const waiting=state.phase==='PHOTO'&&d.index>=2&&!assets.lunaSequence?.placed;$('#nextBtn').disabled=waiting;$('#nextBtn').innerHTML=waiting?'等露娜把照片放好…':`${d.index===d.lines.length-1?d.button:'继续'} <span>→</span>`;}
function nextLine(){if(!dialog||state.phase==='PHOTO'&&dialog.index>=2&&!assets.lunaSequence?.placed)return;if(dialog.index<dialog.lines.length-1){dialog.index++;renderLine();}else{let done=dialog.onDone;dialog=null;closeModal('#dialogue');setInspection(null);done?.();}}
function opening(){showDialog({title:'桥边，还亮着一盏灯',kicker:'序章 · 橙花桥',tag:'伊莲娜 · 夜雾里的等候',object:'frame-empty',lines:[['桥灯学徒','天快亮了。你来收最后一盏桥灯，却看见一位奶奶仍站在雾里。身旁的台座上，放着一只空相框。'],['伊莲娜','我知道自己有个家。只是门前的花、孩子的脸……都快想不清了。'],['伊莲娜','相框空了，我连回家的方向都想不清了。孩子，你能陪我找找吗？'],['桥灯学徒','系一双鞋，做一份点心，再折一朵花。广场上的人会帮你，把她留下的关心重新做一遍。']],button:'去寻找记忆',onDone:()=>{change('START');toast('点击地标自动走近，或用 WASD 移动。靠近后按 E 调查。');}});}
function goTo(key){if(!started||modal||paused)return;if(key==='dog'){assets.dogInteracting=true;autoTarget={key,pos:actors.dog.root.position.clone().add(new T.Vector3(-.6,0,-.45))};return;}if(key==='letter'){autoTarget={key,pos:new T.Vector3(-4.2,0,7.5)};return;}if(key.startsWith('npc:')){autoTarget={key,pos:new T.Vector3(...NPCS[key.slice(4)].stand)};toast('正走向'+NPCS[key.slice(4)].name+'。');return;}if(key==='gate'){autoTarget={key,pos:new T.Vector3(0,0,31.5)};return;}if(key==='elena'){autoTarget={key,pos:actors.elena.root.position.clone().add(new T.Vector3(-.8,0,-.8))};return;}const h=MEMORIES[key];if(!h)return;autoTarget={key,pos:new T.Vector3(...h.stand)};hintKey=key;toast(`正走向${h.place}。按移动键可取消自动行走。`);}
function inspect(key){if(!started||paused||modal)return;autoTarget=null;if(key==='dog'){assets.dogPetUntil=time+4;showDialog({title:'这条路，有它陪你',kicker:'但丁 · 小小引路人',object:null,tag:'一位毛茸茸的朋友',lines:[['桥灯学徒','你轻轻唤了它一声。它抬起脸，像是早就认得你。'],['但丁',state.phase==='TO_GATE'?'它望向花桥，又回头看看你。今晚的路，可以慢慢走。':state.found.length===0?'它在旧鞋铺附近停了停，又回头望你。那里似乎有什么值得记住。':'它陪你站了一会儿。你往前走时，它也会跟上。']],button:'一起走吧',onDone:()=>{assets.dogInteracting=false;}});return;}if(key==='letter'){showDialog({title:'未送出的信',kicker:'明晚的故事 · 尚未开放',object:'book-closed',tag:'乐师桌上的信',lines:[['马特奥','这封信我带了很久。收信的人，一直不知道有人想向他道谢。'],['桥灯学徒','今晚的路已经亮了。下一次，也许可以陪另一个人，把没说完的话带回家。']],button:'把明晚留给这封信',onDone:()=>{toast('今晚先歇一会儿。下一章「未寄出的信」尚未开放。');}});return;}if(key.startsWith('npc:')){talkToNpc(key.slice(4));return;}if(key==='elena'){showDialog({title:'等一条回家的路',kicker:'伊莲娜',object:'frame-empty',tag:'桥口 · 伊莲娜',lines:[['伊莲娜',state.phase==='TO_GATE'?'灯都亮了。孩子，陪我走一段吧。':state.found.length?'你亲手做的那些小事……我好像慢慢记起来了。':'我记得门前的灯，却想不清回家的方向了。你愿意替我看看那些旧物吗？']],button:'继续旅程',onDone:()=>{}});return;}
 if(state.found.includes(key)){replayMemory(key);return;}if(state.phase!=='EXPLORE')return;change('INSPECT',key);const data=MEMORIES[key];player.position.set(...data.stand);player.rotation.y=Math.atan2(data.pos[0]-player.position.x,data.pos[2]-player.position.z);modal='#activity';activity.open(key,result=>{finishPickup();state.creations[key]=result;save();modal=null;const lines=data.lines.map(l=>[...l]);if(key==='recipe')lines.splice(1,0,['伊莲娜',result.sugar===1?'少放一点糖也好。你们会有自己的做法。':result.sugar===3?'今天做得甜一点，也好。你愿意为别人做这份点心，我就很高兴。':'原来你也喜欢这个味道。以后，做给你想照顾的人吃吧。']);if(key==='flower')lines.splice(1,0,['伊莲娜','露娜第一次也折得不太齐。可我把它留了好多年。你这朵，也很好。']);showDialog({title:data.title,kicker:'亲手留下的记忆 · '+data.place,object:data.model,tag:data.name,lines,button:'把这段记忆交给桥灯',onDone:()=>{modal='#activity';activity.open('lamp',()=>{modal=null;change('REMEMBER');hotspots.find(h=>h.key===key).prop.visible=false;chime(data.lamp);applyCreations();toast('第'+state.found.length+'段记忆回来了，你亲手点亮了桥灯。');if(state.phase==='PHOTO')photoReveal();else hintKey=null;});}});});}
function cancelActivity(){finishPickup();if(state.phase==='MEMORY'){const key=state.pending;state={...state,phase:'EXPLORE',pending:null};if(key&&assets[key+'Prop'])assets[key+'Prop'].visible=true;save();}modal=null;updateHUD();toast('先放在这里，稍后还能继续。');}
function replayMemory(key){const fromJournal=modal==='#journal';if(fromJournal)closeModal('#journal');const d=MEMORIES[key];showDialog({title:d.title,kicker:'记忆回看 · 不重复计数',tag:d.name,object:d.model,lines:[d.lines[2],['留灯记忆册',d.note]],button:'合上记忆',onDone:()=>{if(fromJournal)openJournal();}});}
function photoReveal(){soundscape.play('page-turn',.9);assets.lunaSequence={elapsed:0,placed:!!state.photoPlaced};assets.photo.visible=!!state.photoPlaced;if(state.photoPlaced){actors.luna.root.position.set(.2,0,36.98);actors.luna.root.rotation.y=0;assets.photo.position.copy(assets.photoTarget);}showDialog({title:'她的名字，被轻轻唤起',kicker:'第二章 · 照片',tag:'人间 · 家中的祭坛',object:'book-open',lines:[['桥灯学徒','食谱的夹层里，露出一张完整的照片。照片里的笑容，和桥边的她一模一样。你亲手做过的那些小事，终于有了一个名字。'],['露娜 · 人间','妈妈，奶奶的照片在这儿！我还记得她教我折花。今天的点心，我想'+recipeEcho(state.creations)+'。'],['人间的灯火','露娜抱着照片跑来，停在家里的小供桌前，把照片轻轻放进一直空着的相框。那朵纸花，也有了一个被留下的位置。'],['伊莲娜 · 桥的这一边',state.creations.recipe?.sugar===1?'少放一点糖也好。露娜，你们会有自己的做法。原来，我留下的那些小事，还陪着你。':'原来你已经会自己系鞋带了。以后，也会做给自己喜欢的人吃。这样真好。']],button:'陪她过桥',onDone:()=>{soundscape.play('bridge-open',.8);change('PHOTO_DONE');applyState();toast('沿花瓣向前。停下来时，伊莲娜也会等你。');}});}
function bridgeRest(){autoTarget=null;companionHeard.add('rest');showDialog({title:'桥上，歇一会儿',kicker:'不赶路的片刻',tag:'花开在脚下',object:'paper-flower',lines:[['桥灯学徒','她以后还会每年折花、每年做点心吗？'],['伊莲娜','会有忙得忘记的时候，也会有她自己的日子。我不想让想念，变成她的负担。'],['伊莲娜','她愿意照顾自己、也关心别人，我留下的那些小事，就还在。']],button:'再陪她走一段',onDone:()=>{toast('不必赶路。灯会等你。');}});}
$('#bridgeRest').onclick=bridgeRest;$('#touchBarrier').onclick=()=>{bridgeJourney.reach=1;bridgeJourney.crossTime=bridgeJourney.t;toast('结界回应了你的手掌。向前走，她就在身旁。');};
function endingScene(){soundscape.play('farewell',.8);autoTarget=null;endingTime=0;showDialog({title:'今晚，我能回家了',kicker:'终章 · 门后的暖光',tag:'桥的尽头',object:'paper-flower',lines:[['伊莲娜','原来我留下的那些小事，已经成了她自己的生活。'],['伊莲娜','谢谢你，孩子。替我告诉她：你往前走，我就知道家还在。'],['露娜 · 人间','我把鞋带系好了。点心就'+recipeEcho(state.creations)+'，花也放在窗边。奶奶，我明天还要去看看更远的地方。'],['伊莲娜','去吧。以后有人需要的时候，你也替他留一盏灯。'],['桥灯学徒','你放慢脚步，让她先走向暖光。花桥上的灯，一直亮到门后。']],button:'为她留着这盏灯',onDone:()=>{change('FINISH');complete();}});}
function complete(){state.phase='COMPLETE';$('#endingKeepsake').textContent=Object.values(state.creations||{}).map(c=>c.note).filter(Boolean).join(' ');save();openModal('#ending');applyState();}
function openJournal(){if(modal&&modal!=='#ending')return;$('#journalCards').innerHTML=Object.entries(MEMORIES).map(([k,d],i)=>{const found=state.found.includes(k);return `<article class="memory-card ${found?'':'locked'}"><small>第 ${['一','二','三'][i]} 盏灯 · ${d.place}</small><h3>${found?d.title:'尚未找回的记忆'}</h3><p>${found?d.lines[2][1]:d.name+'，仍在广场等你。'}</p>${found&&state.creations[k]?.note?'<p class=personal-memory>'+state.creations[k].note+'</p>':''}${found?`<button data-replay="${k}">再听一次</button>`:''}</article>`;}).join('');$('#journalCards').querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>replayMemory(b.dataset.replay));openModal('#journal');}
function hint(){if(modal||paused)return;if(freeRoam){const stops=['npc:musician','npc:baker','npc:keeper','letter'];const key=stops[(assets.postgameHintIndex||0)%stops.length];assets.postgameHintIndex=(assets.postgameHintIndex||0)+1;goTo(key);return;}if(state.phase==='TO_GATE'){goTo('gate');toast('沿桥上的花瓣走，城门在正前方。');return;}const remaining=Object.keys(MEMORIES).filter(k=>!state.found.includes(k));if(!remaining.length)return;remaining.sort((a,b)=>player.position.distanceTo(new T.Vector3(...MEMORIES[a].stand))-player.position.distanceTo(new T.Vector3(...MEMORIES[b].stand)));hintKey=remaining[0];goTo(hintKey);}
function setWalking(actor,moving,dt){if(!actor)return;if(moving&&!actor.moving){if(actor.walk){actor.walk.paused=false;actor.walk.play();}actor.moving=true;}if(!moving&&actor.moving){if(actor.walk){actor.walk.paused=true;actor.walk.time=.12;actor.mixer.update(0);}actor.moving=false;}if(moving)actor.mixer.update(dt*.8);}
function playPickup(key){const a=actors.apprentice,clip=a.clips.find(c=>c.name!=='walk');if(!clip)return;a.walk?.stop();a.moving=false;a.pick=a.mixer.clipAction(clip);a.pick.reset().setLoop(T.LoopOnce,1);a.pick.clampWhenFinished=true;a.pick.play();a.pickKey=key;a.grabbed=false;}
function finishPickup(){const a=actors.apprentice;if(a.pick){a.pick.stop();a.pick=null;if(a.walk){a.walk.reset().play();a.walk.time=.12;a.walk.paused=true;a.mixer.update(0);}}if(assets.heldProp){assets.heldProp.removeFromParent();assets.heldProp=null;}}
function updatePickup(dt){const a=actors.apprentice;if(!a?.pick)return;a.mixer.update(dt);if(a.pick.time>2.2&&!a.grabbed){a.grabbed=true;soundscape.play('pickup',1);const hand=a.model.getObjectByName('mixamorig:RightHand')||a.model.getObjectByName('mixamorigRightHand');if(hand){const root=assets[MEMORIES[a.pickKey].model].scene.clone(true),b=new T.Box3().setFromObject(root),size=b.getSize(new T.Vector3()),c=b.getCenter(new T.Vector3()),holder=new T.Group();root.position.sub(c);holder.add(root);holder.scale.setScalar(.13/Math.max(size.x,size.y,size.z));hand.add(holder);holder.position.set(.025,0,.015);assets.heldProp=holder;}assets[a.pickKey+'Prop'].visible=false;}}
// Dedicated object-inspection renderer. It never changes the game object or its stored state.
const inspectRenderer=new T.WebGLRenderer({alpha:true,antialias:true});inspectRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));inspectRenderer.outputColorSpace=T.SRGBColorSpace;inspectRenderer.toneMapping=T.ACESFilmicToneMapping;inspectRenderer.toneMappingExposure=1.4;$('#objectView').append(inspectRenderer.domElement);const inspectScene=new T.Scene(),inspectCamera=new T.PerspectiveCamera(35,1,.01,30);inspectScene.add(new T.HemisphereLight(0xffffff,0x8a5670,3));let il=new T.DirectionalLight(0xffdbab,3);il.position.set(3,4,5);inspectScene.add(il);let inspected=null;
function setInspection(name){if(inspected)inspectScene.remove(inspected);inspected=null;if(!name||!assets[name])return;inspected=new T.Group();const content=cloneSkeleton(assets[name].scene),b=new T.Box3().setFromObject(content),s=b.getSize(new T.Vector3()),c=b.getCenter(new T.Vector3());content.position.sub(c);inspected.add(content);inspected.scale.setScalar(1.8/Math.max(s.x,s.y,s.z));inspectScene.add(inspected);inspected.rotation.y=-.3;inspectCamera.position.set(0,.55,4.5);inspectCamera.lookAt(0,0,0);}
function safePosition(next){next.x=T.MathUtils.clamp(next.x,-5.8,5.8);next.z=T.MathUtils.clamp(next.z,.3,39.3);const unlocked=['TO_GATE','ENDING','COMPLETE'].includes(state.phase);if(!unlocked&&next.z>13.3){next.z=13.3;if(time>walkTime+3){toast('三盏灯还没有全部亮起，先找回广场上的记忆。');walkTime=time;}}if(next.z>=30)next.x=T.MathUtils.clamp(next.x,-4.9,4.9);if(next.z>13.3&&next.z<30)next.x=T.MathUtils.clamp(next.x,-1.4,1.4);for(const c of colliders){if(Math.abs(next.x-c.x)<c.w/2+.22&&Math.abs(next.z-c.z)<c.d/2+.22)return false;}return true;}
function updateMove(dt){if(!started||paused||modal){setWalking(actors.apprentice,false,dt);return;}let dx=0,dz=0;if(keys.has('w')||keys.has('arrowup'))dz++;if(keys.has('s')||keys.has('arrowdown'))dz--;if(keys.has('a')||keys.has('arrowleft'))dx++;if(keys.has('d')||keys.has('arrowright'))dx--;let moving=dx!==0||dz!==0;let dir=new T.Vector3();if(moving){autoTarget=null;const forward=new T.Vector3(Math.sin(yaw),0,Math.cos(yaw)),right=new T.Vector3(-Math.cos(yaw),0,Math.sin(yaw));dir.addScaledVector(forward,dz).addScaledVector(right,-dx).normalize();}else if(autoTarget){dir.copy(autoTarget.pos).sub(player.position);dir.y=0;if(dir.length()<.13){const key=autoTarget.key;autoTarget=null;if(key!=='gate')inspect(key);return;}dir.normalize();moving=true;}
 if(moving){const distance=(autoTarget?.key==='gate'&&player.position.z>14&&player.position.z<30?1.35:2.2)*dt,candidate=player.position.clone().addScaledVector(dir,distance);if(safePosition(candidate))player.position.copy(candidate);else{const slide=player.position.clone();slide.x=candidate.x;if(safePosition(slide))player.position.copy(slide);else{slide.copy(player.position);slide.z=candidate.z;if(safePosition(slide))player.position.copy(slide);else if(autoTarget){autoTarget=null;toast('前面有陈设，请绕过它再靠近。');}}}player.rotation.y=Math.atan2(dir.x,dir.z);}
 setWalking(actors.apprentice,moving,dt);if(state.phase==='TO_GATE'&&player.position.z>=31&&Math.abs(player.position.x)<=1.5){change('AT_GATE');endingScene();} }
function updateElena(dt){const a=actors.elena;if(!a)return;if(['TO_GATE','ENDING','COMPLETE'].includes(state.phase)){let target=player.position.clone().add(new T.Vector3(.95,0,-.15));if(state.phase==='ENDING'||state.phase==='COMPLETE')target.set(0,0,34.4);if(player.position.z>14&&player.position.z<30)target.x=T.MathUtils.clamp(target.x,-1.1,1.1);let dir=target.sub(a.root.position);dir.y=0;const distance=dir.length(),move=distance>(['ENDING','COMPLETE'].includes(state.phase) ? .05 : .35);if(move){a.root.position.addScaledVector(dir.normalize(),Math.min(distance,dt*(distance>2?2.6:1.8)));a.root.rotation.y=Math.atan2(dir.x,dir.z);}setWalking(a,move,dt);if(state.phase==='COMPLETE'){a.root.visible=a.root.position.z<34.25;}}
 else setWalking(a,false,dt);
}
function updateCamera(dt){let target,pos;if(!started){target=new T.Vector3(0,1.7,10);pos=new T.Vector3(-8,5.6,-6);}else if(assets.dogInteracting&&modal==='#dialogue'&&dialog?.kicker?.startsWith('但丁')){target=actors.dog.root.position.clone().add(new T.Vector3(0,.4,0));pos=actors.dog.root.position.clone().add(new T.Vector3(1.45,1.12,-1.8));}else if(state.phase==='PHOTO'&&dialog?.index>=1){target=new T.Vector3(.1,.94,37.5);pos=new T.Vector3(-1.7,1.65,34.7);}else if(['ENDING','COMPLETE'].includes(state.phase)&&!freeRoam){target=new T.Vector3(0,1.4,33.2);pos=new T.Vector3(-4,3.2,28.2);}else if(viewFirst){target=player.position.clone().add(new T.Vector3(Math.sin(yaw)*4,1.45,Math.cos(yaw)*4));pos=player.position.clone().add(new T.Vector3(0,1.45,0));}else{target=player.position.clone().add(new T.Vector3(Math.sin(yaw)*1.4,1.05,Math.cos(yaw)*1.4));pos=player.position.clone().add(new T.Vector3(-Math.sin(yaw)*5.1,3.3,-Math.cos(yaw)*5.1));}camera.position.lerp(pos,1-Math.exp(-dt*4));camera.lookAt(target);actors.apprentice&&(actors.apprentice.root.visible=!viewFirst||['MEMORY'].includes(state.phase));}
function projectLabel(button,position){const v=position.clone().project(camera);const visible=v.z>-1&&v.z<1&&Math.abs(v.x)<.96&&Math.abs(v.y)<.9;button.style.display=visible&&!modal&&started?'block':'none';button.style.left=`${(v.x*.5+.5)*innerWidth}px`;button.style.top=`${(-v.y*.5+.5)*innerHeight}px`;}
function updateHotspots(){$('#world').dataset.version='petal-journey-v3';$('#world').dataset.creations=JSON.stringify(state.creations||{});$('#world').dataset.phase=state.phase;$('#world').dataset.position=player.position.toArray().map(n=>n.toFixed(2)).join(',');$('#world').dataset.loaded=loadedCount;nearest=null;let best=1.85;for(const h of hotspots){const distance=player.position.distanceTo(new T.Vector3(...h.data.stand));const eligible=state.phase==='EXPLORE'||(freeRoam&&state.phase==='COMPLETE');projectLabel(h.button,new T.Vector3(h.data.pos[0],h.data.pos[1]+.8,h.data.pos[2]));if(!eligible)h.button.style.display='none';h.button.classList.toggle('target',hintKey===h.key);h.ring.material.opacity=.45+Math.sin(time*2)*.17;if(distance<best&&eligible){nearest=h.key;best=distance;}}
 for(const h of npcSpots){projectLabel(h.button,h.actor.root.position.clone().add(new T.Vector3(0,h.data.height+.4,0)));if(!['EXPLORE','TO_GATE'].includes(state.phase)&&!freeRoam)h.button.style.display='none';if(player.position.distanceTo(new T.Vector3(...h.data.stand))<best){nearest='npc:'+h.key;best=player.position.distanceTo(new T.Vector3(...h.data.stand));}}if(assets.letterButton){projectLabel(assets.letterButton,new T.Vector3(-5.1,1.2,7.9));if(!freeRoam)assets.letterButton.style.display='none';if(freeRoam&&player.position.distanceTo(new T.Vector3(-4.2,0,7.5))<best){nearest='letter';best=player.position.distanceTo(new T.Vector3(-4.2,0,7.5));}}if(actors.elena){projectLabel(assets.npcButton,actors.elena.root.position.clone().add(new T.Vector3(0,2.15,0)));if(!['EXPLORE','TO_GATE'].includes(state.phase))assets.npcButton.style.display='none';if(player.position.distanceTo(actors.elena.root.position)<1.85&&best>1.4)nearest='elena';}
 if(actors.dog){projectLabel(assets.dogButton,actors.dog.root.position.clone().add(new T.Vector3(0,.92,0)));if(!['EXPLORE','TO_GATE','COMPLETE'].includes(state.phase))assets.dogButton.style.display='none';if(!modal&&player.position.distanceTo(actors.dog.root.position)<1.6&&best>1){nearest='dog';best=player.position.distanceTo(actors.dog.root.position);}}const show=nearest&&started&&!paused&&!modal;$('#interaction').style.display=show?'block':'none';if(show)$('#interactBtn span').textContent=nearest==='dog'?'和小狗打个招呼':nearest==='elena'?'和伊莲娜说话':nearest==='letter'?'读这封未送出的信':nearest.startsWith('npc:')?'和'+NPCS[nearest.slice(4)].name+'说话':state.found.includes(nearest)?'回看这段记忆':'调查'+MEMORIES[nearest].name;}
function chime(i){soundscape.play('lamp-'+(i+1),.85);}
async function enableSound(){try{await soundscape.enable();$('#soundBtn').textContent='声音：开';$('#soundBtn').setAttribute('aria-pressed','true');}catch(error){soundscape.disable();$('#soundBtn').textContent='声音：关';$('#soundBtn').setAttribute('aria-pressed','false');toast('声音未能启动，请再点击声音按钮。');console.error(error);}}
$('#soundBtn').onclick=()=>{wantsSound=!soundscape.enabled;try{localStorage.setItem('leave-light-sound',wantsSound?'on':'off');}catch{}if(wantsSound)enableSound();else{soundscape.disable();$('#soundBtn').textContent='声音：关';$('#soundBtn').setAttribute('aria-pressed','false');}};
$('#startBtn').onclick=()=>start(false);$('#continueBtn').onclick=()=>start(true);$('#nextBtn').onclick=nextLine;$('#interactBtn').onclick=()=>nearest&&inspect(nearest);$('#hintBtn').onclick=hint;$('#journalBtn').onclick=openJournal;$('#closeJournal').onclick=()=>{closeModal('#journal');if(state.phase==='COMPLETE'&&!freeRoam)openModal('#ending');};$('#endingJournal').onclick=()=>{closeModal('#ending');openJournal();};
function pause(){if(!started)return;if(modal==='#pause'){resume();return;}if(modal)return;paused=true;save();openModal('#pause');}
function resume(){paused=false;closeModal('#pause');$('#restartConfirm').hidden=true;}
$('#pauseBtn').onclick=pause;$('#resumeBtn').onclick=resume;$('#restartBtn').onclick=()=>$('#restartConfirm').hidden=false;$('#cancelRestart').onclick=()=>$('#restartConfirm').hidden=true;$('#confirmRestart').onclick=()=>{clearingSave=true;try{localStorage.removeItem(SAVE);}catch{}location.reload();};$('#playAgain').onclick=()=>{clearingSave=true;try{localStorage.removeItem(SAVE);}catch{}location.reload();};$('#retry').onclick=()=>location.reload();$('#returnPlaza').onclick=()=>{closeModal('#ending');freeRoam=true;player.position.set(0,0,3);yaw=0;paused=false;updateHUD();toast('灯会留到天亮。去听完那支曲子，或再和大家聊聊吧。');};
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)||(key===' '&&(!(e.target instanceof HTMLButtonElement)||modal==='#dialogue')))e.preventDefault();if(e.repeat)return;if(modal==='#dialogue'&&[' ','enter'].includes(key)){e.preventDefault();nextLine();return;}if(key==='escape'){if(!$('#gesturePanel').hidden){$('#gesturePanel').hidden=true;return;}if(modal==='#journal')$('#closeJournal').click();else pause();return;}if(modal)return;if(key==='j'){openJournal();return;}if(key==='e'&&nearest){inspect(nearest);return;}if(key==='v'){viewFirst=!viewFirst;toast(viewFirst?'第一人称视角':'跟随学徒视角');return;}keys.add(key);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();save();});
renderer.domElement.addEventListener('pointerdown',e=>{if(modal||!started)return;dragging={x:e.clientX,yaw};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(dragging)yaw=dragging.yaw-(e.clientX-dragging.x)*.006;});renderer.domElement.addEventListener('pointerup',()=>dragging=false);
for(const b of document.querySelectorAll('[data-move]')){const key={forward:'w',back:'s',left:'a',right:'d'}[b.dataset.move];b.onpointerdown=e=>{e.preventDefault();keys.add(key);b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>keys.delete(key);}
window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});
let saveClock=0;renderer.setAnimationLoop(now=>{const dt=Math.min(.05,(now-last)/1000);last=now;time+=dt;updateMove(dt);if(started&&!paused){updateElena(dt);updateLuna(dt);updateNPCs(dt);updateDog(dt);updateCompanion();updatePickup(dt);}updateCamera(dt);for(let i=0;i<lamps.length;i++){const target=state.found.includes(Object.keys(MEMORIES)[i])?1:0;lamps[i].amount=T.MathUtils.lerp(lamps[i].amount,target,dt*2);lamps[i].light.intensity=7*lamps[i].amount;lamps[i].bulb.material.emissiveIntensity=4*lamps[i].amount;}bridgeJourney.tick(started&&!paused?dt:0,{position:player.position,rotation:player.rotation.y,active:started&&!paused&&!modal,state});$('#touchBarrier').hidden=!(started&&!paused&&!modal&&state.phase==='TO_GATE'&&player.position.z>11.5&&player.position.z<14.05);$('#bridgeRest').hidden=!(started&&!paused&&!modal&&state.phase==='TO_GATE'&&player.position.z>18&&player.position.z<27&&!companionHeard.has('rest')); if(assets.fire)assets.fire.rotation.y=Math.sin(time*.04)*.025;updateHotspots();if(time>toastUntil)$('#toast').classList.remove('show');soundscape.tick(dt,{started,paused:paused||document.hidden,dialogue:!!modal,memories:state.found.length,moving:actors.apprentice?.moving&&!modal,onBridge:player.position.z>14&&player.position.z<30});if(started&&!paused&&!modal&&time>saveClock){save();saveClock=time+3;}renderer.render(world,camera);if(inspected&&modal==='#dialogue'){inspected.rotation.y+=dt*.13;const el=$('#objectView'),w=el.clientWidth,h=el.clientHeight;if(w&&h){inspectRenderer.setSize(w,h,false);inspectCamera.aspect=w/h;inspectCamera.updateProjectionMatrix();inspectRenderer.render(inspectScene,inspectCamera);}}});
