window.gameStatus=()=>({phase:state.phase,found:[...state.found],position:player.position.toArray(),npc:actors.elena?.root.position.toArray(),autoTarget:autoTarget?.key,nearest,modal,loaded:loadedCount,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,animations:Object.fromEntries(Object.entries(actors).map(([k,a])=>[k,a.clips.map(c=>({name:c.name,duration:c.duration}))]))});
